"""Pydantic schemas for CodeMind AI API and engine data models."""

from __future__ import annotations

from enum import Enum
from typing import List, Optional
from pydantic import BaseModel, Field


class IssueCategory(str, Enum):
    bug = "bug"
    security = "security"
    performance = "performance"
    style = "style"
    architecture = "architecture"


class IssueSeverity(str, Enum):
    low = "low"
    medium = "medium"
    high = "high"
    critical = "critical"


class ReviewIssue(BaseModel):
    """A single code review issue generated by the LLM."""
    id: str = Field(description="Unique identifier for this issue")
    category: IssueCategory
    severity: IssueSeverity
    line_start: Optional[int] = None
    line_end: Optional[int] = None
    title: str = Field(description="Short one-line description")
    explanation: str = Field(description="Detailed explanation of the issue and why it matters")
    suggestion: str = Field(description="Concrete suggestion / replacement code")
    memory_applied: Optional[str] = Field(
        default=None,
        description="Explains which Hindsight memory influenced this review item (if any)"
    )


class ReviewRequest(BaseModel):
    """Incoming review request from the API."""
    code: str = Field(description="Python source code to review")
    filename: Optional[str] = Field(default="untitled.py")
    context: Optional[str] = Field(
        default=None,
        description="Optional extra context (e.g. project type, team notes)"
    )


class ReviewResponse(BaseModel):
    """Full review result returned by the API."""
    filename: str
    total_lines: int
    issues: List[ReviewIssue]
    summary: str = Field(description="High-level review summary")
    memories_recalled: str = Field(description="The raw recalled memory context used in this review")
    ast_summary: str = Field(description="AST analysis summary")


class FeedbackDecision(str, Enum):
    accept = "accept"
    reject = "reject"


class FeedbackRequest(BaseModel):
    """Developer feedback on a specific review issue."""
    issue_id: str
    decision: FeedbackDecision
    suggestion_text: str = Field(description="The suggestion text that was accepted/rejected")
    code_context: str = Field(description="Relevant code snippet for context")
    reason: Optional[str] = Field(default=None, description="Developer's rationale")


class FeedbackResponse(BaseModel):
    status: str
    message: str
    memory_stored: bool


class ConventionAddRequest(BaseModel):
    """Manually add a team coding rule."""
    rule: str
    author: Optional[str] = None


class HealthResponse(BaseModel):
    status: str
    hindsight_connected: bool
    groq_model: str
    bank_id: str
